package com.badrulamin.University_Management.controller;  import com.badrulamin.University_Management.entity.FacultyAttendance; import com.badrulamin.University_Management.payload.response.PagedResponse; import com.badrulamin.University_Management.service.FacultyAttendanceService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Pageable; import org.springframework.data.domain.Sort; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.annotation.RequestParam;  @RestController @RequestMapping("/api/faculty-attendance") @RequiredArgsConstructor public class FacultyAttendanceController {      private final FacultyAttendanceService facultyAttendanceService;      @PreAuthorize("hasAuthority('FACULTY_VIEW')")     @GetMapping     public ResponseEntity<PagedResponse<FacultyAttendance>> findAll(             @RequestParam(defaultValue = "0") int page,             @RequestParam(defaultValue = "20") int size,             @RequestParam(defaultValue = "id") String sortBy,             @RequestParam(defaultValue = "asc") String sortDir) {         Sort sort = sortDir.equalsIgnoreCase("desc") ? Sort.by(sortBy).descending() : Sort.by(sortBy).ascending();         Pageable pageable = PageRequest.of(page, size, sort);         Page<FacultyAttendance> paged = facultyAttendanceService.findAll(pageable);         PagedResponse<FacultyAttendance> response = new PagedResponse<>(paged.getContent(), paged.getNumber(), paged.getSize(), paged.getTotalElements(), paged.getTotalPages(), paged.isFirst(), paged.isLast());         return ResponseEntity.ok(response);     }      @PreAuthorize("hasAuthority('FACULTY_VIEW')")     @GetMapping("/{id}")     public ResponseEntity<FacultyAttendance> findById(@PathVariable Long id) {         return ResponseEntity.ok(facultyAttendanceService.findById(id));     }      @PreAuthorize("hasAuthority('FACULTY_VIEW')")     @PostMapping     public ResponseEntity<FacultyAttendance> save(@Valid @RequestBody FacultyAttendance facultyAttendance) {         return ResponseEntity.ok(facultyAttendanceService.save(facultyAttendance));     }      @PreAuthorize("hasAuthority('FACULTY_VIEW')")     @PutMapping("/{id}")     public ResponseEntity<FacultyAttendance> update(@PathVariable Long id, @Valid @RequestBody FacultyAttendance facultyAttendance) {         return ResponseEntity.ok(facultyAttendanceService.update(id, facultyAttendance));     }      @PreAuthorize("hasAuthority('FACULTY_VIEW')")     @DeleteMapping("/{id}")     public ResponseEntity<Void> delete(@PathVariable Long id) {         facultyAttendanceService.delete(id);         return ResponseEntity.noContent().build();     } }